import os,pathlib, subprocess, shutil, sys
ROOT=pathlib.Path(__file__).resolve().parent
OUT=ROOT/'build'; OUT.mkdir(exist_ok=True)
# Variables holding per-process resource handles (surfaces, sprites, data structures, paths, sounds...) are never copied
# between games; generate their names from the documented variable table.
import re
_names=[m.group(1) for m in re.finditer(r'^\s*\d+\s*\(\s*[0-9A-Fa-f]+\):\s*(\S+)',(ROOT/'vendor/HeatSignatureModLoader/docs/known_variable_properties.txt').read_text(),re.M)]
_handle=re.compile(r'Surface|Sprite|Icon|List$|Lists|Grid|Map$|Maps|Path$|Paths|Sound|Buffer|Particle|Emitter|System|Queue|Stack|Font|Shader|Texture|Vertex|Audio|Music|Background|Timeline|Pool|Cache',re.I)
_skip=sorted(n for n in _names if _handle.search(n) and 'Priority' not in n)
(ROOT/'src/HandleVars.h').write_text('#pragma once\n// Generated by build.py from known_variable_properties.txt: per-process resource handles, never copied.\n'
    'static const char* const HANDLE_VARS[]={'+','.join('"%s"'%n for n in _skip)+'};\n')
import hashlib
# Build id = content hash of the plugin sources; players with different builds get a warning in game.
_sources=sorted((ROOT/'src').glob('*.[ch]*'))
_build=int(hashlib.sha256(b''.join(p.read_bytes() for p in _sources)).hexdigest()[:8],16)
# --dev DIR: a developer build for the test copies, adding the extra sources in DIR (the private developer extension: the developer
# channel used by the dev tools) with HS_COOP_DEVTOOLS defined. Without it (package.py) the plugin has no dev channel.
dev=pathlib.Path(sys.argv[sys.argv.index('--dev')+1]).resolve() if '--dev' in sys.argv else None
extra=(['-DHS_COOP_DEVTOOLS','-I'+str(dev),*map(str,sorted(dev.glob('*.cpp')))] if dev else [])
cmd=[str(ROOT/'tools/zig-x86_64-windows-0.14.1/zig.exe'),'c++','-target','x86-windows-gnu','-std=c++17','-O2','-shared','-DHS_COOP_BUILD=0x%08xu'%_build,*([f"-DHS_COOP_PACKET_VERSION={os.environ['HS_COOP_PACKET_VERSION']}"] if os.environ.get('HS_COOP_PACKET_VERSION') else []),'-DWIN32_LEAN_AND_MEAN','-DNOMINMAX','-I'+str(ROOT/'vendor/HeatSignatureModLoader/ModLoader'),'-I'+str(ROOT/'src'),str(ROOT/'src/CoopProbe.cpp'),str(ROOT/'src/Console.cpp'),str(ROOT/'src/Net.cpp'),str(ROOT/'src/Seed.cpp'),*[str(ROOT/'src'/f) for f in ('Snapshot.cpp','Missions.cpp','Guards.cpp','TimePolicy.cpp','Frame.cpp','Presence.cpp','Visuals.cpp','TestMenu.cpp','Objects.cpp','GalaxySync.cpp','Crate.cpp','Hull.cpp','Lobby.cpp','Steam.cpp','Report.cpp')],*extra,'-ladvapi32','-lws2_32','-lbcrypt','-lgdi32','-luser32','-o',str(OUT/'HS_Coop.dll')]
subprocess.run(cmd,check=True)
print('Built %08x%s'%(_build,' (developer build)' if dev else ''))
